            :disabled="rebuilding"
            @click="rebuildIndex"
          >
            {{ rebuilding ? '重建中…' : '重建索引' }}
          </button>
        </template>
        <button type="button" class="btn primary" @click="openUpload">上传文档</button>
      </template>
    </PageHeader>

    <div v-if="capabilityDisabled" class="gate" data-testid="knowledge-gate" role="status">
      <p class="gate-title">「知识库」能力未启用</p>
