from pathlib import Path
p = Path('src/stores/capabilities.ts')
s = p.read_text()
s = s.replace("""import { mcpApi } from '@/api/mcp'
import { skillsApi } from '@/api/skills'
import type { McpAvailableServer, McpAvailableTool, SkillCatalogItem } from '@/types'""", """import { knowledgeApi } from '@/api/knowledge'
import { mcpApi } from '@/api/mcp'
import { skillsApi } from '@/api/skills'
import { aggregateCategories } from '@/utils/knowledge'
import type { McpAvailableServer, McpAvailableTool, SkillCatalogItem } from '@/types'""")

s = s.replace("""  const loading = ref(false)
  const loaded = ref(false)
  const error = ref<string | null>(null)""", """  const loading = ref(false)
  const loaded = ref(false)
  const error = ref<string | null>(null)
  /** 知识库分类候选：后端没有分类目录端点，只能从可见文档聚合。 */
  const knowledgeCategories = ref<string[]>([])
  const knowledgeCategoriesLoaded = ref(false)
  const loadingKnowledgeCategories = ref(false)""")

s = s.replace("""  /** 设置页改动后让下一次选择重新拉取。 */
  function invalidate(): void {
    loaded.value = false
  }""", """  /**
   * 懒加载分类候选（最多 100 篇可见文档）。
   *
   * - 能力关闭时后端返回 403：静默保持空列表，由输入栏提示「未启用」；
   * - 失败不阻断聊天主流程，也不写全局 error，避免影响技能/MCP 目录。
   */
  async function loadKnowledgeCategories(force = false): Promise<void> {
    if (loadingKnowledgeCategories.value) return
    if (knowledgeCategoriesLoaded.value && !force) return
    loadingKnowledgeCategories.value = true
    try {
      const page = await knowledgeApi.documents({ limit: 100 })
      knowledgeCategories.value = aggregateCategories(page.items)
      knowledgeCategoriesLoaded.value = true
    } catch {
      knowledgeCategories.value = []
    } finally {
      loadingKnowledgeCategories.value = false
    }
  }

  /** 设置页改动后让下一次选择重新拉取。 */
  function invalidate(): void {
    loaded.value = false
    knowledgeCategoriesLoaded.value = false
  }""")

s = s.replace("""    loadingTools,
    load,
    loadTools,""", """    loadingTools,
    knowledgeCategories,
    knowledgeCategoriesLoaded,
    loadingKnowledgeCategories,
    load,
    loadTools,
    loadKnowledgeCategories,""")
p.write_text(s)

p = Path('src/views/chat/ChatView.vue')
s = p.read_text()
s = s.replace("""onMounted(async () => {
  void system.load()
  void capabilityCatalog.load()""", """onMounted(async () => {
  void system.load()
  void capabilityCatalog.load()""")
# add watcher after onMounted block's closing
s = s.replace("""  if (activeId.value) await loadConversation(activeId.value)
})

watch(
  () => system.defaultModel,""", """  if (activeId.value) await loadConversation(activeId.value)
})

// 能力开关加载完成后才拉知识库分类，避免对关闭能力的用户发无效请求。
watch(
  () => system.capabilities.knowledge,
  (enabled) => {
    if (enabled) void capabilityCatalog.loadKnowledgeCategories()
  },
  { immediate: true },
)

watch(
  () => system.defaultModel,""")

s = s.replace("""        :mcp-tools="capabilityCatalog.mcpTools"
""", """        :mcp-tools="capabilityCatalog.mcpTools"
        :knowledge-categories="capabilityCatalog.knowledgeCategories"
""")
p.write_text(s)
