Implementation code:

```ts
const pollFailures = ref(0)
let pollInFlight = false
const retryingId = ref<string | null>(null)

async function refreshStatuses(): Promise<void> {
  if (pollInFlight) return
  pollInFlight = true
  try {
    const page = await knowledgeApi.documents({ ...listParams(true), limit: 20 })
    const fresh = [...page.items]
    const known = new Set(page.items.map((document) => document.id))
    const interim = items.value.filter(
      (document) => isInterimStatus(document.status) && !known.has(document.id),
    )
    const removed: string[] = []
    await Promise.all(
      interim.slice(0, 20).map(async (document) => {
        try {
          fresh.push(await knowledgeApi.get(document.id))
        } catch (cause) {
          if (cause instanceof ApiRequestError && cause.status === 404) {
            removed.push(document.id)
            return
          }
          throw cause
        }
      }),
    )
    items.value = applyPolledDocuments(items.value, fresh, removed, statusFilter.value)
    stats.value = page.stats
    const freshSelected = selected.value
      ? fresh.find((document) => document.id === selected.value?.id)
      : undefined
    if (freshSelected) selected.value = freshSelected
    pollFailures.value = 0
  } catch (cause) {
    if (cause instanceof ApiRequestError && cause.code === 'capability_disabled') {
      capabilityDisabled.value = true
      stopPolling()
      return
    }
    pollFailures.value += 1
    if (pollFailures.value >= 3) {
      stopPolling()
      ElMessage.warning('知识库状态刷新连续失败，已暂停自动轮询')
    }
  } finally {
    pollInFlight = false
  }
}
```

Note: `Promise.all` with throw inside → rejects; remaining gets continue; catch handles. If one 404 and another throws, removed lost; fine.

